"use strict";

let WaveState = null;
let initialized = false;

let g_DeathActive = false;
let g_DeathRemain = 0;
let g_DeathTicking = false;

let g_SelectedShop1Ability = "";

function StartDeathTimer(seconds) {
    // seconds 必须是 >= 1 的整数，否则直接不启动
    const s = Math.max(0, Math.floor(seconds));
    g_DeathRemain = s;

    const row = $("#DeathRow");
    if (row) row.RemoveClass("Hidden");

    // 立即刷新一次文本
    const label = $("#DeathTimerLabel");
    if (label) label.text = $.Localize("#Revive") + g_DeathRemain + "s";

    // 确保只有一条循环在跑
    if (!g_DeathTicking) {
        g_DeathTicking = true;
        TickDeathTimer();
    }
}

function TickDeathTimer() {
    // 循环唯一出口：不激活就停止并释放 ticking 锁
    if (!g_DeathActive) {
        g_DeathTicking = false;
        return;
    }

    // 每秒递减一次
    g_DeathRemain -= 1;

    if (g_DeathRemain <= 0) {
        const row = $("#DeathRow");
        if (row) row.AddClass("Hidden");
        g_DeathActive = false;
        g_DeathTicking = false;
        return;
    }

    const label = $("#DeathTimerLabel");
    if (label) label.text = $.Localize("#Revive") + g_DeathRemain + "s";

    $.Schedule(1.0, TickDeathTimer);
}


function OnHeroFakeDeath(event) {
    
    const localHero = Players.GetPlayerHeroEntityIndex(Players.GetLocalPlayer());

    if (event.entindex !== localHero)
        return;

    const row = $("#DeathRow");
    if (!row) return;

    if (event.is_dead === 1) {
        const dur = 10;
        const seconds = isFinite(dur) ? Math.ceil(dur) : 0;

        g_DeathActive = true;

        // duration 为 0 的情况：仍显示但用 1 秒兜底，避免“显示后立刻不走”
        StartDeathTimer(seconds > 0 ? seconds : 1);
    } else {
        g_DeathActive = false;
        g_DeathRemain = 0;
        row.AddClass("Hidden");
        // ticking 锁不强行改，TickDeathTimer 下一轮会自动释放
    }
}

function OnShop1DummySelection(event) {
    const row = $("#Shop1DummyRow");
    const icon = $("#Shop1DummyAbilityIcon");
    if (!row || !icon) return;

    const abilityName = event && event.ability ? event.ability : "";
    if (!abilityName) {
        row.AddClass("Hidden");
        icon.abilityname = "";
        icon.ClearPanelEvent("onmouseover");
        icon.ClearPanelEvent("onmouseout");
        g_SelectedShop1Ability = "";
        return;
    }

    g_SelectedShop1Ability = abilityName;
    row.RemoveClass("Hidden");
    icon.abilityname = abilityName;

    icon.ClearPanelEvent("onmouseover");
    icon.ClearPanelEvent("onmouseout");
    icon.SetPanelEvent("onmouseover", function () {
        $.DispatchEvent("DOTAShowAbilityTooltip", icon, abilityName);
    });
    icon.SetPanelEvent("onmouseout", function () {
        $.DispatchEvent("DOTAHideAbilityTooltip", icon);
    });
}

(function () {

    GameEvents.Subscribe("hero_fake_death", OnHeroFakeDeath);
    GameEvents.Subscribe("shop1_dummy_selection", OnShop1DummySelection);

    // 监听 wave_info/state
    CustomNetTables.SubscribeNetTableListener("wave_info", (table, key, data) => {
        if (key === "state") {
            WaveState = data;

            // 第一次收到数据 → 显示整个 UI
            if (!initialized) {

                $("#TopBarContainer").RemoveClass("Hidden");
                $("#TopBarContainer").AddClass("Visible");

                $("#TopBarContent").RemoveClass("Hidden");
                $("#TopBarContent").AddClass("Visible");

                $("#WaveRow").RemoveClass("Hidden");
                $("#WaveRow").AddClass("Visible");

                initialized = true;
            }
        }
    });


    function Update() {
        if (WaveState) {

            const now = Game.GetGameTime();

            /* 第一行：Next / Alive / Boss */
            const nextRemain = Math.max(WaveState.next_wave_time - now, 0);
            $("#NextLabel").text = $.Localize("#Next") + Math.ceil(nextRemain) + "s";

            const expansionProgress = WaveState.expansion_progress || 0;
            const expansionGoal = WaveState.expansion_goal || 5;
            $("#AliveLabel").text = $.Localize("#ExpansionProgress");

            // ------- 进度条更新 ---------
            let pct = expansionGoal > 0 ? (expansionProgress / expansionGoal) : 0;
            if (pct < 0) pct = 0;
            if (pct > 1) pct = 1;

            const bar = $("#AliveBarFill");
            bar.style.width = (pct * 100) + "%";

            let color = "#FFFFFF";      // 安全：白色

            if (pct >= 0.40 && pct < 0.70) color = "#E7BA01";      // 黄色
            else if (pct >= 0.70 && pct < 0.85) color = "#FF7F00"; // 橙色
            else if (pct >= 0.85 && pct <= 1.00) color = "#FF3F3F"; // 红色
            else if (pct > 1.0) color = "#A60000";                 // 深红（超过上限）

            bar.style.backgroundColor = color;
            $("#AliveBarText").text = expansionProgress + " / " + expansionGoal;

            const bossRemain = Math.max(WaveState.next_boss_time - now, 0);
            $("#BossLabel").text = $.Localize("#Boss") + Math.ceil(bossRemain) + "s";

            /* 第二行：Start 或 Wave */
            const preRemain = Math.max(WaveState.pre_delay_end_time - now, 0);

            if (preRemain > 0) {
                $("#StartLabel").visible = true;
                $("#WaveLabel").visible = false;
                $("#StartLabel").text = $.Localize("#Start") + Math.ceil(preRemain) + "s";
            } else {
                $("#StartLabel").visible = false;
                $("#WaveLabel").visible = true;
                $("#WaveLabel").text = $.Localize("#Wave") + (WaveState.current_wave || 0);
            }
        }

        $.Schedule(0.1, Update);
    }

    Update();

    const barContainer = $("#AliveBarContainer");
    if (barContainer) {
        barContainer.SetPanelEvent("onmouseover", function () {
            const progress = WaveState ? (WaveState.expansion_progress || 0) : 0;
            const goal = WaveState ? (WaveState.expansion_goal || 5) : 5;
            const tip = $.Localize("#ExpansionProgressTooltip_1") + " " + (goal - progress) + " " + $.Localize("#ExpansionProgressTooltip_2");
            $.DispatchEvent("DOTAShowTextTooltip", barContainer, tip);
        });
        barContainer.SetPanelEvent("onmouseout", function () {
            $.DispatchEvent("DOTAHideTextTooltip", barContainer);
        });
    }

})();


